makeMtLab(document.getElementById("lab-l7"),{id:"l7",scenarios:[{"label": "Ví dụ: Tìm nút cổ chai", "note": "Máy có chu kỳ dài nhất giới hạn cả dây chuyền.", "steps": [{"t": "Chu kỳ ba máy", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trạm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td>2,0 s<\/td><\/tr><tr><td>M2<\/td><td>1,8 s<\/td><\/tr><tr><td>M3<\/td><td>1,5 s<\/td><\/tr><\/tbody><\/table>"}, {"t": "Nút cổ chai là M1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trạm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td class=\"hi\">M1<\/td><td class=\"hi\">2,0 s<\/td><\/tr><tr><td>M2<\/td><td>1,8 s<\/td><\/tr><tr><td>M3<\/td><td>1,5 s<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Máy nào là nút cổ chai?", "o": ["M1", "M2", "M3"], "a": 0}}, {"t": "Năng lực dây chuyền", "html": "<p class=\"mt-calc\">3 600 s / 2,0 s = 1 800 hộp/giờ<\/p>"}]}, {"label": "Ví dụ: Thời gian chạy lệnh 6 000 hộp", "note": "Chuyển đổi cộng số lượng nhân chu kỳ nút cổ chai.", "steps": [{"t": "Thời gian sản xuất", "html": "<p class=\"mt-calc\">6 000 × 2,0 s = 12 000 s = 200 phút<\/p>"}, {"t": "Cộng chuyển đổi", "html": "<p class=\"mt-calc\">200 + 15 = <b>215 phút<\/b><\/p>", "ask": {"q": "Tổng thời gian chạy lệnh là bao nhiêu phút?", "o": ["200", "215", "530"], "a": 1}}]}, {"label": "Ví dụ: Thay M1 bằng máy nhanh hơn", "note": "Nút cổ chai dịch sang máy khác.", "steps": [{"t": "M1 mới: 1,6 s", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trạm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td>1,6 s<\/td><\/tr><tr><td>M2<\/td><td class=\"hi\">1,8 s<\/td><\/tr><tr><td>M3<\/td><td>1,5 s<\/td><\/tr><\/tbody><\/table>"}, {"t": "Nút cổ chai mới là M2", "html": "<p class=\"mt-calc\">3 600 / 1,8 = <b>2 000 hộp/giờ<\/b><\/p>", "say": "<p>Năng lực chỉ tăng tới mức của máy chậm thứ hai.<\/p>", "ask": {"q": "Năng lực mới là bao nhiêu hộp/giờ?", "o": ["2 250", "2 000", "1 800"], "a": 1}}]}, {"label": "Bẫy: Cộng chu kỳ các máy", "note": "Ba máy làm việc song song trên ba hộp khác nhau.", "steps": [{"t": "Cộng 2,0 + 1,8 + 1,5", "html": "<p class=\"mt-calc\">5,3 s/hộp → 3 600 / 5,3 ≈ 679 hộp/giờ<\/p>", "ask": {"q": "Con số 679 hộp/giờ đúng không?", "o": ["Đúng", "Sai: phải dùng nút cổ chai"], "a": 1}}, {"t": "Sửa: dùng chu kỳ nút cổ chai", "html": "<p class=\"mt-calc\">3 600 / 2,0 = 1 800 hộp/giờ<\/p>", "say": "<p>5,3 s là thời gian một hộp đi qua cả ba máy (thời gian xuyên suốt), không phải nhịp ra hộp.<\/p>"}]}, {"label": "Lỗi: Không kiểm tra bỏ bước", "note": "Hộp chưa dán nắp vẫn được ghi đạt.", "steps": [{"t": "Hộp 08812 qua M1 rồi tới M3", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Công đoạn<\/th><th scope=\"col\">Đã qua?<\/th><\/tr><\/thead><tbody><tr><td>10 Rót<\/td><td>Có<\/td><\/tr><tr><td>20 Dán nắp<\/td><td class=\"bad\">Không<\/td><\/tr><tr><td>30 Cân<\/td><td>Đang cân<\/td><\/tr><\/tbody><\/table>"}, {"t": "Sửa: M3 kiểm tra công đoạn trước", "html": "<p class=\"mt-calc\">Nếu công đoạn 20 chưa hoàn tất → MES báo lỗi, không ghi đạt<\/p>", "say": "<p>Đây là chức năng quản lý quy trình của MESA.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l7"),"l7",[{"kind": "num", "t": "Năng lực và thời gian", "d": "<p>Dùng routing của bài. Trả lời bằng một số.<\/p>", "items": [{"q": "Năng lực dây chuyền bao nhiêu hộp/giờ?", "a": 1800, "unit": "hộp/giờ"}, {"q": "Lệnh 9 000 hộp, chuyển đổi 15 phút. Tổng bao nhiêu phút?", "a": 315, "unit": "phút"}, {"q": "Nếu M1 đổi thành 1,5 s, năng lực mới bao nhiêu hộp/giờ?", "a": 2000, "unit": "hộp/giờ"}], "hints": ["Nút cổ chai là máy có chu kỳ dài nhất.", "Thời gian = chuyển đổi + số lượng × chu kỳ nút cổ chai.", "Khi M1 nhanh lên, kiểm tra lại máy nào chậm nhất."], "why": "3 600/2,0 = 1 800; 9 000 × 2 s = 300 phút + 15 = 315; M1 = 1,5 s thì M2 (1,8 s) thành nút cổ chai: 2 000 hộp/giờ."}, {"kind": "pick", "t": "BOM hay routing?", "d": "<p>Thông tin này nằm ở đâu?<\/p>", "cats": ["BOM", "Routing"], "items": [{"q": "Hộp cần 1 nắp", "a": 0}, {"q": "Dán nắp ở máy M2", "a": 1}, {"q": "Chu kỳ cân 1,5 s", "a": 1}, {"q": "0,500 kg hạt mỗi hộp", "a": 0}, {"q": "Chuyển đổi 15 phút", "a": 1}], "hints": ["BOM: vật tư gì, bao nhiêu.", "Routing: bước nào, ở đâu, bao lâu."], "why": "Vật tư và số lượng thuộc BOM; công đoạn, trạm, thời gian thuộc routing."}, {"kind": "order", "t": "Đường đi của một hộp", "d": "<p>Sắp xếp các công đoạn của SP-07.<\/p>", "items": ["Công đoạn 10: rót hạt ở M1", "Công đoạn 20: dán nắp, in date ở M2", "Công đoạn 30: cân kiểm tra ở M3", "Đóng thùng 24 hộp"], "hints": ["Số công đoạn tăng dần theo thứ tự làm.", "Đóng thùng làm sau khi hộp đã đạt cân kiểm tra."], "why": "10 → 20 → 30 → đóng thùng."}]);
mesSim(document.getElementById("sim-l7"),Object.assign({id:"l7"},{kind:"calc",title:"Năng lực chuyền và thời gian chạy lệnh",
 inputs:[{k:"c1",l:"M1 rót",min:1,max:3,step:0.1,v:2,u:"s"},{k:"c2",l:"M2 dán nắp",min:1,max:3,step:0.1,v:1.8,u:"s"},{k:"c3",l:"M3 cân",min:1,max:3,step:0.1,v:1.5,u:"s"},
  {k:"q",l:"Số lượng lệnh",min:1000,max:12000,step:500,v:6000,u:"hộp"},{k:"co",l:"Chuyển đổi",min:0,max:60,step:5,v:15,u:"phút"}],
 outputs:[{k:"bn",l:"Nút cổ chai",f:V=>Math.max(V.c1,V.c2,V.c3),fmt:(v,V)=>["M1","M2","M3"][[V.c1,V.c2,V.c3].indexOf(v)]+" · "+mesFmt(v,1)+" s"},
  {k:"cap",l:"Năng lực chuyền",f:(V,R)=>3600/R.bn,fmt:v=>mesFmt(v)+" hộp/giờ"},{k:"wrong",l:"Nếu cộng chu kỳ (sai)",f:V=>3600/(V.c1+V.c2+V.c3),fmt:v=>mesFmt(v)+" hộp/giờ",cls:()=>"er"},
  {k:"run",l:"Thời gian chạy lệnh",big:1,f:(V,R)=>V.co+V.q*R.bn/60,fmt:v=>mesFmt(v,1)+" phút",x:(V,R)=>mesFmt(V.co)+" + "+mesFmt(V.q)+" × "+mesFmt(R.bn,1)+" s / 60"}],
 bars:(V,R)=>[["M1",V.c1,V.c1===R.bn?"er":"a",mesFmt(V.c1,1)+" s"],["M2",V.c2,V.c2===R.bn?"er":"a",mesFmt(V.c2,1)+" s"],["M3",V.c3,V.c3===R.bn?"er":"a",mesFmt(V.c3,1)+" s"]],
 tasks:[{t:"Với số liệu của khóa, lệnh 6 000 hộp chạy bao lâu? So năng lực đúng với cách cộng chu kỳ (sai).",ok:"15 + 6 000 × 2,0 / 60 = 215 phút; năng lực 1 800 hộp/giờ, không phải 679.",check:s=>s.V.q===6000&&s.V.c1===2&&Math.abs(s.R.run-215)<0.01},
  {t:"Nâng cấp M1 xuống 1,6 s. Máy nào thành nút cổ chai, năng lực mới là bao nhiêu?",ok:"M2 1,8 s thành nút cổ chai: 2 000 hộp/giờ. Nâng một máy chỉ có ích tới khi máy kế tiếp chậm nhất.",check:s=>s.V.c1<=1.6&&s.R.bn===s.V.c2},
  {t:"Tìm cách để lệnh 12 000 hộp chạy dưới 6 giờ (360 phút).",hint:"Cần nút cổ chai ≤ khoảng 1,7 s và chuyển đổi ngắn.",check:s=>s.V.q===12000&&s.R.run<360}]}));

